        roundRect(60, 70, 120, 130, 6); ctx.stroke();
        // Window cross
        ctx.beginPath();
        ctx.moveTo(120, 70); ctx.lineTo(120, 200);
        ctx.moveTo(60, 135); ctx.lineTo(180, 135);
        ctx.stroke();
        // Sun in window
