        // Sunbeam on floor
        ctx.fillStyle = "rgba(255,235,150,0.4)";
        ctx.beginPath();
        ctx.moveTo(60, 280); ctx.lineTo(180, 280); ctx.lineTo(200, 500); ctx.lineTo(40, 500);
        ctx.closePath(); ctx.fill();

        // Poster (BE BRAVE)
