        ctx.fill();
        // Milk glass
        ctx.fillStyle = "#FAFAFA";
        roundRect(sn.x + 36, sn.y + 18, 16, 28, 3); ctx.fill();
        ctx.strokeStyle = "#1A1A1A"; ctx.lineWidth = 2;
        roundRect(sn.x + 36, sn.y + 18, 16, 28, 3); ctx.stroke();
